src/styles/carbon.css.body:
/* IBM Carbon Design System — 精确还原核心 token */
:root {
  /* 色板 */
  --cds-blue-60: #0f62fe;
  --cds-blue-70: #0043ce;
  --cds-blue-80: #002d9c;
  --cds-blue-10: #edf5ff;
  --cds-gray-10: #f4f4f4;
  --cds-gray-20: #e0e0e0;
  --cds-gray-30: #c6c6c6;
  --cds-gray-40: #a8a8a8;
  --cds-gray-50: #8d8d8d;
  --cds-gray-60: #6f6f6f;
  --cds-gray-70: #525252;
  --cds-gray-80: #393939;
  --cds-gray-90: #262626;
  --cds-gray-100: #161616;
  --cds-white: #ffffff;
  --cds-green-40: #24a148;
  --cds-green-10: #defbe6;
  --cds-red-60: #da1e28;
  --cds-red-10: #fff1f1;
  --cds-yellow-30: #f1c21b;
  --cds-yellow-10: #fcf4d6;
  --cds-teal-60: #007d79;
  --cds-purple-60: #8a3ffc;
  --cds-orange-40: #eb6200;

  /* 字体 */
  --cds-font-sans: 'IBM Plex Sans', 'Helvetica Neue', Arial, sans-serif;
  --cds-font-mono: 'IBM Plex Mono', 'Menlo', monospace;

  /* 间距 — Carbon 8px 基准 */
  --cds-spacing-01: 0.125rem;
  --cds-spacing-02: 0.25rem;
  --cds-spacing-03: 0.5rem;
  --cds-spacing-04: 0.75rem;
  --cds-spacing-05: 1rem;
  --cds-spacing-06: 1.5rem;
  --cds-spacing-07: 2rem;
  --cds-spacing-08: 2.5rem;
  --cds-spacing-09: 3rem;

  /* Carbon 无圆角 */
  --cds-radius: 0;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: var(--cds-font-sans);
  background: var(--cds-gray-10);
  color: var(--cds-gray-100);
  font-size: 0.875rem;
  line-height: 1.42857;
  letter-spacing: 0.16px;
  -webkit-font-smoothing: antialiased;
}

/* ===== 全局导航栏 — Carbon UI Shell ===== */
.global-header {
  background: var(--cds-gray-100);
  height: 3rem;
  display: flex;
  align-items: center;
  padding: 0 var(--cds-spacing-05);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--cds-gray-80);
}

.global-header .brand {
  display: flex;
  align-items: center;
  gap: var(--cds-spacing-03);
  color: var(--cds-white);
  font-weight: 600;
  font-size: 0.875rem;
  letter-spacing: 0;
}

.global-header .logo {
  width: 1.5rem;
  height: 1.5rem;
  background: var(--cds-blue-60);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0;
}

.global-header .sep {
  width: 1px;
  height: 1rem;
  background: var(--cds-gray-70);
  margin: 0 var(--cds-spacing-02);
}

.global-header .product {
  font-weight: 400;
  color: var(--cds-gray-30);
  font-size: 0.8125rem;
}

.global-header .actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: var(--cds-spacing-05);
  color: var(--cds-gray-30);
  font-size: 0.75rem;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 0;
  background: var(--cds-green-40);
  display: inline-block;
  margin-right: 4px;
}

/* ===== 页面标题 ===== */
.page-header {
  background: var(--cds-white);
  border-bottom: 1px solid var(--cds-gray-20);
  padding: var(--cds-spacing-06) var(--cds-spacing-07);
}

.breadcrumb {
  font-size: 0.75rem;
  color: var(--cds-gray-60);
  margin-bottom: var(--cds-spacing-03);
  display: flex;
  gap: var(--cds-spacing-03);
  letter-spacing: 0;
}

.breadcrumb .current { color: var(--cds-gray-100); }

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 400;
  line-height: 1.25;
  letter-spacing: 0;
}

.page-header .subtitle {
  font-size: 0.875rem;
  color: var(--cds-gray-60);
  margin-top: var(--cds-spacing-03);
  max-width: 48rem;
  letter-spacing: 0;
}

/* ===== 主区域 ===== */
.main { padding: var(--cds-spacing-06) var(--cds-spacing-07); }

/* ===== 统计 ===== */
.stats-row {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr));
  gap: 1px;
  background: var(--cds-gray-20);
  border: 1px solid var(--cds-gray-20);
  margin-bottom: var(--cds-spacing-06);
}

.stat {
  background: var(--cds-white);
  padding: var(--cds-spacing-04) var(--cds-spacing-05);
}

.stat .label {
  font-size: 0.6875rem;
  color: var(--cds-gray-60);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--cds-spacing-02);
}

.stat .value {
  font-size: 1.5rem;
  font-weight: 300;
  line-height: 1.2;
  letter-spacing: 0;
}

.stat .value small {
  font-size: 0.75rem;
  color: var(--cds-gray-60);
  font-weight: 400;
  margin-left: 4px;
}

/* ===== 步骤导航 — Carbon Progress Indicator ===== */
.progress-steps {
  background: var(--cds-white);
  border: 1px solid var(--cds-gray-20);
  margin-bottom: var(--cds-spacing-06);
  display: flex;
  overflow-x: auto;
}

.progress-step {
  flex: 1;
  min-width: 9rem;
  padding: var(--cds-spacing-04) var(--cds-spacing-05);
  border-right: 1px solid var(--cds-gray-20);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: var(--cds-spacing-02);
  transition: background 0.15s;
}

.progress-step:last-child { border-right: none; }
.progress-step:hover { background: var(--cds-gray-10); }
.progress-step.active { background: var(--cds-blue-10); box-shadow: inset 0 3px 0 0 var(--cds-blue-60); }

.step-num {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  background: var(--cds-gray-20);
  color: var(--cds-gray-70);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
  letter-spacing: 0;
}

.progress-step.active .step-num { background: var(--cds-blue-60); color: var(--cds-white); }
.progress-step.completed .step-num { background: var(--cds-green-40); color: var(--cds-white); }

.step-label { font-size: 0.75rem; font-weight: 600; white-space: nowrap; letter-spacing: 0; }
.step-desc { font-size: 0.6875rem; color: var(--cds-gray-60); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: 0; }

/* ===== 面板 ===== */
.panel {
  background: var(--cds-white);
  border: 1px solid var(--cds-gray-20);
  margin-bottom: var(--cds-spacing-05);
}

.panel-header {
  padding: var(--cds-spacing-05) var(--cds-spacing-06);
  border-bottom: 1px solid var(--cds-gray-20);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--cds-spacing-03);
}

.panel-header h2 { font-size: 1rem; font-weight: 600; letter-spacing: 0; }
.panel-meta { font-size: 0.75rem; color: var(--cds-gray-60); letter-spacing: 0; }
.panel-body { padding: var(--cds-spacing-06); }
.panel-body.no-pad { padding: 0; }

/* ===== 表单 — Carbon Text Input ===== */
.form-row { display: flex; gap: var(--cds-spacing-05); flex-wrap: wrap; margin-bottom: var(--cds-spacing-05); }
.form-group { flex: 1; min-width: 12rem; display: flex; flex-direction: column; gap: var(--cds-spacing-02); }
.form-label { font-size: 0.75rem; color: var(--cds-gray-70); letter-spacing: 0.02em; }

.form-input, .form-select {
  height: 2.5rem;
  padding: 0 var(--cds-spacing-04);
  font-size: 0.875rem;
  font-family: var(--cds-font-sans);
  background: var(--cds-gray-10);
  border: none;
  border-bottom: 1px solid var(--cds-gray-50);
  color: var(--cds-gray-100);
  outline: none;
  letter-spacing: 0.16px;
}

.form-input:focus, .form-select:focus {
  border-bottom-color: var(--cds-blue-60);
  background: var(--cds-white);
  outline: 1px solid var(--cds-blue-60);
  outline-offset: -1px;
}

/* ===== 按钮 — Carbon Button ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cds-spacing-05);
  padding: 0 var(--cds-spacing-05);
  height: 2.5rem;
  font-size: 0.875rem;
  font-family: var(--cds-font-sans);
  font-weight: 400;
  letter-spacing: 0.16px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
  border-radius: 0;
}

.btn-primary { background: var(--cds-blue-60); color: var(--cds-white); }
.btn-primary:hover { background: var(--cds-blue-70); }
.btn-secondary { background: var(--cds-gray-80); color: var(--cds-white); }
.btn-secondary:hover { background: var(--cds-gray-90); }
.btn-ghost { background: transparent; color: var(--cds-blue-60); border: 1px solid var(--cds-blue-60); }
.btn-ghost:hover { background: var(--cds-blue-10); }
.btn-sm { height: 2rem; font-size: 0.75rem; padding: 0 var(--cds-spacing-04); }

/* ===== 表格 — Carbon Data Table ===== */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8125rem;
  letter-spacing: 0.16px;
}

.data-table th {
  background: var(--cds-gray-90);
  color: var(--cds-white);
  text-align: left;
  padding: var(--cds-spacing-03) var(--cds-spacing-04);
  font-weight: 600;
  font-size: 0.75rem;
  letter-spacing: 0.16px;
  white-space: nowrap;
  border-right: 1px solid var(--cds-gray-80);
}

.data-table th:last-child { border-right: none; }

.data-table td {
  padding: var(--cds-spacing-03) var(--cds-spacing-04);
  border-bottom: 1px solid var(--cds-gray-20);
  color: var(--cds-gray-80);
  vertical-align: middle;
  letter-spacing: 0.16px;
}

.data-table tr:hover td { background: var(--cds-gray-10); }
.mono { font-family: var(--cds-font-mono); font-size: 0.75rem; letter-spacing: 0; }

/* ===== 标签 — Carbon Tag ===== */
.tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 var(--cds-spacing-03);
  height: 1.5rem;
  font-size: 0.75rem;
  font-weight: 400;
  border-radius: 12px;
  white-space: nowrap;
  letter-spacing: 0.16px;
  line-height: 1;
}

.tag-green { background: var(--cds-green-10); color: var(--cds-green-40); }
.tag-red { background: var(--cds-red-10); color: var(--cds-red-60); }
.tag-yellow { background: var(--cds-yellow-10); color: #8e6a00; }
.tag-blue { background: var(--cds-blue-10); color: var(--cds-blue-60); }
.tag-gray { background: var(--cds-gray-20); color: var(--cds-gray-70); }
.tag-teal { background: #d9fbfb; color: var(--cds-teal-60); }
.tag-purple { background: #f6f2ff; color: var(--cds-purple-60); }

/* ===== 工具卡片 ===== */
.tool-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
  gap: var(--cds-spacing-05);
}

.tool-card {
  border: 1px solid var(--cds-gray-20);
  padding: var(--cds-spacing-04);
  background: var(--cds-white);
  transition: border-color 0.15s;
}

.tool-card:hover { border-color: var(--cds-blue-60); }

.tool-name {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: var(--cds-spacing-02);
  display: flex;
  justify-content: space-between;
  align-items: center;
  letter-spacing: 0;
}

.tool-role { font-size: 0.75rem; color: var(--cds-gray-60); margin-bottom: var(--cds-spacing-03); letter-spacing: 0; }
.tool-price { font-size: 0.75rem; color: var(--cds-green-40); font-weight: 500; margin-bottom: var(--cds-spacing-02); letter-spacing: 0; }

.tool-fields {
  font-size: 0.6875rem;
  color: var(--cds-gray-70);
  font-family: var(--cds-font-mono);
  background: var(--cds-gray-10);
  padding: var(--cds-spacing-02) var(--cds-spacing-03);
  line-height: 1.5;
  word-break: break-all;
  letter-spacing: 0;
}

/* ===== 模型标签 ===== */
.model-tags { display: flex; flex-wrap: wrap; gap: var(--cds-spacing-03); }

.model-tag {
  padding: 0 var(--cds-spacing-03);
  height: 1.5rem;
  display: inline-flex;
  align-items: center;
  font-size: 0.75rem;
  border-radius: 12px;
  background: var(--cds-gray-10);
  color: var(--cds-gray-70);
  border: 1px solid var(--cds-gray-20);
  letter-spacing: 0.16px;
}

.model-tag.recommended {
  background: var(--cds-blue-60);
  color: var(--cds-white);
  border-color: var(--cds-blue-60);
}

/* ===== 代码块 ===== */
.code-block {
  background: var(--cds-gray-90);
  color: #d4e0ed;
  font-family: var(--cds-font-mono);
  font-size: 0.75rem;
  line-height: 1.6;
  padding: var(--cds-spacing-04) var(--cds-spacing-05);
  overflow-x: auto;
  white-space: pre;
  border-left: 3px solid var(--cds-blue-60);
  letter-spacing: 0;
}

.code-block .k { color: #7eb8da; }
.code-block .s { color: #a8d5a2; }
.code-block .b { color: #f0c674; }
.code-block .c { color: #6b7a8f; font-style: italic; }

/* ===== 通知 ===== */
.notification {
  display: flex;
  align-items: flex-start;
  gap: var(--cds-spacing-03);
  padding: var(--cds-spacing-04) var(--cds-spacing-05);
  border-left: 3px solid var(--cds-blue-60);
  background: var(--cds-blue-10);
  font-size: 0.8125rem;
  color: var(--cds-gray-80);
  margin-bottom: var(--cds-spacing-05);
  letter-spacing: 0.16px;
}

.notification.warning { border-left-color: var(--cds-yellow-30); background: var(--cds-yellow-10); }
.notification.success { border-left-color: var(--cds-green-40); background: var(--cds-green-10); }
.notif-icon { font-weight: 700; font-size: 1rem; flex-shrink: 0; }

/* ===== 两栏布局 ===== */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: var(--cds-spacing-06); }
@media (max-width: 900px) { .two-col { grid-template-columns: 1fr; } }

/* ===== 步骤内容 ===== */
.step-content { display: none; }
.step-content.active { display: block; }

/* ===== 底部操作栏 ===== */
.action-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--cds-spacing-05) var(--cds-spacing-06);
  background: var(--cds-white);
  border: 1px solid var(--cds-gray-20);
  margin-top: var(--cds-spacing-05);
  flex-wrap: wrap;
  gap: var(--cds-spacing-04);
}

.action-info { font-size: 0.75rem; color: var(--cds-gray-60); letter-spacing: 0; }
.action-buttons { display: flex; gap: var(--cds-spacing-04); }

/* ===== ICP 层级折叠 ===== */
.icp-layer { border: 1px solid var(--cds-gray-20); margin-bottom: var(--cds-spacing-03); }

.icp-layer-header {
  background: var(--cds-gray-10);
  padding: var(--cds-spacing-03) var(--cds-spacing-05);
  font-weight: 600;
  font-size: 0.8125rem;
  display: flex;
  justify-content: space-between;
  cursor: pointer;
  letter-spacing: 0;
}

.icp-layer-body { padding: var(--cds-spacing-05); display: none; }
.icp-layer.open .icp-layer-body { display: block; }

.icp-field-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr));
  gap: var(--cds-spacing-04);
}

.icp-field { display: flex; flex-direction: column; gap: 2px; }
.icp-field label { font-size: 0.6875rem; color: var(--cds-gray-60); letter-spacing: 0.02em; }

.icp-field .val {
  font-size: 0.8125rem;
  padding: var(--cds-spacing-02) var(--cds-spacing-03);
  background: var(--cds-gray-10);
  border-bottom: 1px solid var(--cds-gray-30);
  font-family: var(--cds-font-mono);
  letter-spacing: 0;
}

/* ===== Toast ===== */
#toast {
  display: none;
  position: fixed;
  bottom: var(--cds-spacing-07);
  left: 50%;
  transform: translateX(-50%);
  background: var(--cds-gray-100);
  color: var(--cds-white);
  padding: var(--cds-spacing-03) var(--cds-spacing-06);
  font-size: 0.8125rem;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
  z-index: 3000;
  border-left: 3px solid var(--cds-green-40);
  white-space: nowrap;
  letter-spacing: 0.16px;
}

/* ===== 字段标签组 ===== */
.field-tags { display: flex; flex-wrap: wrap; gap: 6px; }


/* Euresis shell — Carbon UI Shell alignment */
:root { --shell-width: 16rem; --shell-collapsed-width: 3rem; }
[hidden] { display: none !important; }
.global-header { height: 3rem; padding: 0 1rem 0 0; gap: 0; }
.shell-toggle { width: 3rem; height: 3rem; flex: 0 0 3rem; display: inline-flex; align-items: center; justify-content: center; color: #f4f4f4; background: transparent; border: 0; cursor: pointer; }
.shell-toggle:hover { background: #353535; }
.shell-toggle:focus-visible, .side-nav-item:focus-visible, .btn:focus-visible, .cds-select-trigger:focus-visible { outline: 2px solid #ffffff; outline-offset: -3px; }
.shell-toggle svg { width: 1.25rem; height: 1.25rem; }
.global-header .brand { gap: .75rem; }
.global-header .logo { width: 1.75rem; height: 1.75rem; font-size: 1rem; font-weight: 500; }
.brand-name { font-size: .9375rem; font-weight: 600; }
.global-header .actions { gap: 1rem; }
.environment, .version-label { white-space: nowrap; }
.app-shell { display: flex; min-height: calc(100vh - 3rem); }
.side-nav { width: var(--shell-width); flex: 0 0 var(--shell-width); background: #f4f4f4; border-right: 1px solid #e0e0e0; display: flex; flex-direction: column; transition: width .16s ease, flex-basis .16s ease; overflow: hidden; }
.nav-section-label { padding: 1.25rem 1rem .5rem; font-size: .6875rem; font-weight: 600; letter-spacing: .08em; color: #6f6f6f; text-transform: uppercase; white-space: nowrap; }
.side-nav-item { width: 100%; min-height: 3rem; padding: 0 .875rem; border: 0; border-left: 3px solid transparent; background: transparent; display: flex; align-items: center; gap: .75rem; text-align: left; color: #393939; font: inherit; cursor: pointer; white-space: nowrap; }
.side-nav-item svg { width: 1.25rem; height: 1.25rem; flex: 0 0 1.25rem; }
.side-nav-item:hover { background: #e8e8e8; }
.side-nav-item.active { border-left-color: #0f62fe; background: #e0e0e0; color: #161616; font-weight: 600; }
.nav-item-trailing { margin-left: auto; color: #6f6f6f; }
.side-nav-footer { margin-top: auto; padding-bottom: 1rem; }
.side-nav-note { display: flex; gap: .5rem; align-items: center; padding: .5rem 1rem; font-size: .6875rem; color: #6f6f6f; white-space: nowrap; }
.side-nav-note .status-dot { flex: 0 0 6px; }
.workspace { min-width: 0; flex: 1; }
.app-shell.sidebar-collapsed .side-nav { width: var(--shell-collapsed-width); flex-basis: var(--shell-collapsed-width); }
.app-shell.sidebar-collapsed .nav-section-label, .app-shell.sidebar-collapsed .side-nav-item span, .app-shell.sidebar-collapsed .side-nav-note span:not(.status-dot) { display: none; }
.app-shell.sidebar-collapsed .side-nav-item { justify-content: center; padding: 0; }
.app-shell.sidebar-collapsed .side-nav-item { border-left-width: 0; border-right: 3px solid transparent; }
.app-shell.sidebar-collapsed .side-nav-item.active { border-right-color: #0f62fe; }
.page-header { padding: 1.5rem 2rem; }
.page-title-row { display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; }
.page-header h1 { font-size: 1.75rem; }
.cds-chip { display: inline-flex; align-items: center; gap: .375rem; padding: .375rem .625rem; background: #e0e0e0; color: #393939; font-size: .75rem; white-space: nowrap; }
.main { padding: 1.5rem 2rem 2rem; }
.stats-row { grid-template-columns: repeat(6, minmax(0, 1fr)); }
.stat { min-width: 0; }
.progress-step { position: relative; }
.progress-step:focus-visible { outline: 2px solid #0f62fe; outline-offset: -2px; }
.progress-step { border: 0; border-right: 1px solid #e0e0e0; border-bottom: 3px solid transparent; background: #fff; text-align: left; font-family: inherit; }
.progress-step.active { box-shadow: none; border-bottom-color: #0f62fe; background: #edf5ff; }
.step-num { border-radius: 0; }
.tag, .model-tag { border-radius: 0; }
.tool-card { min-width: 0; }
.btn { transition: background-color .12s ease, border-color .12s ease; }
.form-select { appearance: none; -webkit-appearance: none; border-radius: 0; }
.integration-summary { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1px; border: 1px solid #e0e0e0; background: #e0e0e0; margin-bottom: 1.5rem; }
.integration-summary-card { background: #fff; padding: 1rem; }
.integration-summary-label { color: #6f6f6f; font-size: .75rem; margin-bottom: .5rem; }
.integration-summary-value { font-size: 1.5rem; font-weight: 300; }
.integration-toolbar { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; margin: 1.5rem 0 1rem; }
.integration-toolbar h2 { font-size: 1.125rem; font-weight: 400; margin-bottom: .25rem; }
.integration-toolbar p, .helper-copy { color: #525252; font-size: .8125rem; }
.integration-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 1rem; align-items: start; }
.integration-card { background: #fff; border: 1px solid #e0e0e0; min-width: 0; }
.integration-card-header { display: flex; align-items: flex-start; gap: .75rem; padding: 1rem; border-bottom: 1px solid #e0e0e0; }
.integration-icon { width: 2.5rem; height: 2.5rem; display: flex; align-items: center; justify-content: center; flex: 0 0 2.5rem; background: #edf5ff; color: #0043ce; font-weight: 600; }
.integration-title { min-width: 0; flex: 1; }
.integration-title h3 { font-size: .9375rem; font-weight: 600; margin-bottom: .25rem; }
.integration-title p { font-size: .75rem; color: #6f6f6f; }
.integration-state { margin-left: auto; }
.integration-card-body { padding: 1rem; }
.integration-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: .875rem; }
.integration-field { min-width: 0; display: flex; flex-direction: column; gap: .375rem; }
.integration-field.full { grid-column: 1 / -1; }
.integration-field label { font-size: .75rem; color: #525252; }
.integration-field input, .integration-field textarea { width: 100%; min-width: 0; height: 2.5rem; border: 0; border-bottom: 1px solid #8d8d8d; background: #f4f4f4; padding: 0 .75rem; color: #161616; font: inherit; font-size: .875rem; border-radius: 0; }
.integration-field input:focus, .integration-field textarea:focus { outline: 2px solid #0f62fe; outline-offset: -2px; background: #fff; border-bottom-color: #0f62fe; }
.integration-field input::placeholder { color: #6f6f6f; }
.integration-field .field-help { font-size: .6875rem; color: #6f6f6f; line-height: 1.4; }
.cds-select { position: relative; }
.cds-select-trigger { width: 100%; min-height: 2.5rem; padding: 0 .75rem; border: 0; border-bottom: 1px solid #8d8d8d; background: #f4f4f4; color: #161616; display: flex; align-items: center; justify-content: space-between; text-align: left; font: inherit; font-size: .875rem; cursor: pointer; }
.cds-select-trigger:hover { background: #e8e8e8; }
.cds-select-menu { position: absolute; top: calc(100% + 1px); left: 0; right: 0; z-index: 20; background: #fff; border: 1px solid #8d8d8d; box-shadow: 0 4px 8px rgba(0,0,0,.16); max-height: 15rem; overflow-y: auto; }
.cds-select-option { width: 100%; min-height: 2.5rem; padding: .625rem .75rem; border: 0; background: #fff; color: #161616; text-align: left; font: inherit; cursor: pointer; display: block; }
.cds-select-option:hover, .cds-select-option[aria-selected="true"] { background: #e8e8e8; }
.integration-card-footer { display: flex; align-items: center; justify-content: space-between; gap: .75rem; padding: .875rem 1rem; border-top: 1px solid #e0e0e0; background: #f4f4f4; }
.integration-footer-actions { display: flex; gap: .5rem; flex-wrap: wrap; }
.integration-message { font-size: .75rem; color: #525252; line-height: 1.4; }
.integration-message.success { color: #198038; }
.integration-message.error { color: #da1e28; }
.integration-help { margin-top: 1.5rem; }
.integration-help .code-block { margin-top: .875rem; }
.integration-help code { font-family: var(--cds-font-mono); background: #e0e0e0; padding: 0 .25rem; }
.btn:disabled { opacity: .5; cursor: not-allowed; }
button, input { -webkit-tap-highlight-color: transparent; }
@media (max-width: 1100px) { .stats-row { grid-template-columns: repeat(3,minmax(0,1fr)); } .integration-grid { grid-template-columns: 1fr; } }
@media (max-width: 700px) {
  .side-nav { width: 3rem; flex-basis: 3rem; }
  .side-nav .nav-section-label, .side-nav .side-nav-item span, .side-nav .side-nav-note span:not(.status-dot) { display: none; }
  .side-nav .side-nav-item { justify-content: center; padding: 0; }
  .global-header .product, .global-header .sep, .version-label { display: none; }
  .global-header .actions { font-size: .6875rem; gap: .5rem; }
  .page-header, .main { padding-left: 1rem; padding-right: 1rem; }
  .page-title-row { flex-direction: column; }
  .stats-row { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .integration-summary { grid-template-columns: 1fr; }
  .integration-form-grid { grid-template-columns: 1fr; }
  .integration-field.full { grid-column: auto; }
  .integration-toolbar { flex-direction: column; }
  .action-bar { align-items: flex-start; }
  .action-buttons { flex-wrap: wrap; }
}

/* Carbon toggle switch */
.cds-switch { display: inline-flex; align-items: center; gap: .5rem; font-size: .75rem; color: #525252; cursor: pointer; white-space: nowrap; }
.cds-switch input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.cds-switch-track { width: 2rem; height: 1rem; border: 1px solid #6f6f6f; border-radius: 1rem; background: #c6c6c6; position: relative; flex: 0 0 2rem; transition: background .12s; }
.cds-switch-track::after { content: ''; position: absolute; width: .625rem; height: .625rem; left: .125rem; top: .125rem; background: #fff; border-radius: 50%; transition: transform .12s; }
.cds-switch input:checked + .cds-switch-track { background: #0f62fe; border-color: #0f62fe; }
.cds-switch input:checked + .cds-switch-track::after { transform: translateX(1rem); }
.cds-switch input:focus-visible + .cds-switch-track { outline: 2px solid #0f62fe; outline-offset: 2px; }


/* Euresis responsive Carbon refinement */
html, body { width: 100%; min-width: 0; max-width: 100%; overflow-x: clip; }
body { margin: 0; }
[hidden] { display: none !important; }
button, input, textarea { max-width: 100%; }
button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 2px solid var(--cds-blue-60); outline-offset: 2px; }
.global-header { width: 100%; min-width: 0; padding-inline: 1rem; gap: .75rem; }
.global-header .brand { min-width: 0; }
.global-header .brand-name { white-space: nowrap; }
.global-header .logo { display: none !important; }
.shell-toggle { width: 2rem; height: 2rem; padding: .25rem; display: inline-flex; align-items: center; justify-content: center; flex: 0 0 2rem; border: 0; background: transparent; color: #f4f4f4; cursor: pointer; }
.shell-toggle svg { display: block; width: 1.25rem; height: 1.25rem; }
.app-shell { display: flex; width: 100%; max-width: 100%; min-width: 0; }
.side-nav { flex: 0 0 var(--shell-nav-width, 16rem); width: var(--shell-nav-width, 16rem); min-width: 0; overflow: hidden; transition: width .16s ease, flex-basis .16s ease; }
.app-shell.sidebar-collapsed .side-nav { display: none !important; width: 0 !important; flex-basis: 0 !important; min-width: 0 !important; }
.workspace { flex: 1 1 0; min-width: 0; max-width: 100%; overflow: hidden; }
#workflowView, #integrationsView { min-width: 0; max-width: 100%; }
.page-header, .main { width: 100%; min-width: 0; max-width: 100%; }
.page-title-row > *, .integration-toolbar > *, .integration-card-header > * { min-width: 0; }
.page-header h1 { overflow-wrap: anywhere; }
.subtitle, .integration-title p { overflow-wrap: anywhere; }
.main { padding: 1.5rem clamp(.75rem, 2vw, 2rem) 2rem; }
.stats-row { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 1px; border: 0; background: #e0e0e0; width: 100%; min-width: 0; }
.stat { min-width: 0; padding: 1rem; border-top: 2px solid #0f62fe; background: #fff; }
.stat .label { overflow-wrap: anywhere; line-height: 1.4; }
.stat .value { font-size: clamp(1.25rem, 2vw, 1.75rem); overflow-wrap: anywhere; }
.stat .value small { display: inline-block; margin-left: .25rem; }
.cds-progress-indicator { display: flex; align-items: stretch; width: 100%; min-width: 0; gap: 0; margin: 0 0 1.5rem; padding: 0; border: 0; background: transparent; overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: thin; }
.cds-progress-step { position: relative; display: flex; align-items: flex-start; gap: .75rem; flex: 1 0 9rem; min-width: 9rem; min-height: 4.5rem; padding: .875rem .75rem; border: 0; border-top: 1px solid #c6c6c6; border-bottom: 1px solid #c6c6c6; background: #fff; color: #161616; text-align: left; font: inherit; cursor: pointer; }
.cds-progress-step + .cds-progress-step { border-left: 1px solid #e0e0e0; }
.cds-progress-step:hover { background: #f4f4f4; }
.cds-progress-step.active { border-top: 3px solid #0f62fe; padding-top: calc(.875rem - 2px); background: #edf5ff; }
.cds-progress-marker { display: inline-flex; align-items: center; justify-content: center; width: 1.5rem; height: 1.5rem; flex: 0 0 1.5rem; background: #e0e0e0; color: #393939; font-size: .75rem; font-weight: 600; }
.cds-progress-step.active .cds-progress-marker { background: #0f62fe; color: #fff; }
.cds-progress-step.completed .cds-progress-marker { background: #198038; color: #fff; }
.cds-progress-copy { display: flex; flex-direction: column; min-width: 0; gap: .25rem; }
.cds-progress-label { font-size: .8125rem; font-weight: 600; line-height: 1.3; }
.cds-progress-description { color: #6f6f6f; font-size: .6875rem; line-height: 1.35; white-space: normal; overflow-wrap: anywhere; }
.icp-definition-section { min-width: 0; margin: 1rem 0 1.5rem; }
.icp-section-heading { display: flex; align-items: flex-start; justify-content: space-between; flex-wrap: wrap; gap: 1rem; padding: .25rem 0 1rem; border-bottom: 1px solid #c6c6c6; margin-bottom: .25rem; }
.icp-section-heading h2 { font-size: 1.25rem; font-weight: 400; }
.icp-section-heading p { margin-top: .25rem; color: #6f6f6f; font-size: .8125rem; }
.icp-section-actions { display: flex; gap: .5rem; flex-wrap: wrap; }
.icp-layer { border-bottom: 1px solid #c6c6c6; }
.icp-layer-heading { font: inherit; }
.icp-layer-header { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-height: 3.5rem; padding: .875rem .25rem; border: 0; background: transparent; color: #161616; font: inherit; font-size: .9375rem; font-weight: 600; text-align: left; cursor: pointer; }
.icp-layer-header:hover { background: #f4f4f4; }
.icp-layer-chevron { transition: transform .15s ease; }
.icp-layer.open .icp-layer-chevron { transform: rotate(180deg); }
.icp-layer-body { padding: .5rem 0 1.25rem; }
.icp-field-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
.icp-field { display: flex; flex-direction: column; min-width: 0; gap: .375rem; }
.icp-field label, .model-picker-wrap > label { font-size: .75rem; color: #525252; }
.cds-text-input { width: 100%; min-width: 0; height: 2.5rem; padding: 0 .75rem; border: 0; border-bottom: 1px solid #8d8d8d; border-radius: 0; background: #f4f4f4; color: #161616; font: inherit; font-size: .875rem; }
.cds-text-input:hover { background: #e8e8e8; }
.cds-text-input:focus { outline: 2px solid #0f62fe; outline-offset: -2px; background: #fff; border-bottom-color: #0f62fe; }
.icp-support-grid { align-items: start; min-width: 0; }
.icp-schema-panel { min-width: 0; background: #fff; border: 1px solid #e0e0e0; }
.model-picker-wrap { margin-top: 1.25rem; display: flex; flex-direction: column; gap: .5rem; max-width: 24rem; }
.model-picker { width: 100%; }
.field-help { color: #6f6f6f; font-size: .75rem; line-height: 1.45; }
.generated-queries { display: flex; flex-direction: column; }
.generated-query { display: grid; grid-template-columns: minmax(5rem, auto) minmax(0, 1fr) auto; align-items: center; gap: .75rem; padding: .875rem 1rem; border-bottom: 1px solid #e0e0e0; }
.generated-query:last-child { border-bottom: 0; }
.generated-query code { min-width: 0; color: #393939; font-family: var(--cds-font-mono); font-size: .75rem; overflow-wrap: anywhere; white-space: normal; }
.query-note { color: #6f6f6f; font-size: .75rem; }
.cds-data-table-container { width: 100%; max-width: 100%; min-width: 0; overflow-x: auto; overscroll-behavior-x: contain; }
.data-table { width: 100%; min-width: 38rem; border-collapse: collapse; }
.data-table tbody tr[data-record-row] { cursor: pointer; }
.data-table tbody tr[data-record-row]:focus-visible { outline: 2px solid #0f62fe; outline-offset: -2px; }
.data-table tbody tr[data-record-row]:hover td { background: #edf5ff; }
.cds-modal-backdrop { position: fixed; inset: 0; z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 1rem; background: rgba(22,22,22,.55); }
.cds-modal-backdrop[hidden] { display: none !important; }
.cds-modal { display: flex; flex-direction: column; width: min(42rem, 100%); max-height: min(85dvh, 50rem); background: #fff; box-shadow: 0 12px 32px rgba(0,0,0,.24); }
.cds-modal-header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 1.25rem; border-bottom: 1px solid #e0e0e0; }
.cds-modal-header h2 { font-size: 1.125rem; font-weight: 600; }
.cds-icon-button { width: 2.5rem; height: 2.5rem; border: 0; background: transparent; color: #161616; font-size: 1.75rem; cursor: pointer; }
.cds-modal-body { padding: 1rem 1.25rem; overflow-y: auto; }
.cds-modal-footer { display: flex; justify-content: flex-end; padding: 1rem 1.25rem; border-top: 1px solid #e0e0e0; }
.record-detail-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0; }
.record-detail-item { min-width: 0; padding: .75rem; border-bottom: 1px solid #e0e0e0; }
.record-detail-item dt { color: #6f6f6f; font-size: .75rem; margin-bottom: .375rem; }
.record-detail-item dd { color: #161616; font-size: .875rem; overflow-wrap: anywhere; }
body.modal-open { overflow: hidden; }
button, input, textarea { touch-action: manipulation; }
@media (max-width: 900px) {
  .stats-row { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .icp-field-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 600px) {
  .global-header { height: 3rem; padding-inline: .5rem; gap: .5rem; }
  .global-header .brand { gap: .5rem; font-size: .875rem; }
  .global-header .actions .environment { max-width: 7.5rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .global-header .actions { min-width: 0; gap: .25rem; }
  .app-shell { display: block; }
  .side-nav { width: 100%; }
  .app-shell:not(.sidebar-collapsed) .side-nav { width: 100%; }
  .app-shell.sidebar-collapsed .side-nav { display: none !important; }
  .page-header { padding: 1rem .875rem; }
  .page-header h1 { font-size: 1.375rem; }
  .main { padding: 1rem .875rem 1.5rem; }
  .stats-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stat { padding: .75rem; }
  .stat .label { font-size: .6875rem; }
  .stat .value { font-size: 1.375rem; }
  .cds-progress-indicator { margin-bottom: 1rem; }
  .cds-progress-step { flex-basis: 8.5rem; min-width: 8.5rem; min-height: 4rem; padding: .625rem; gap: .5rem; }
  .cds-progress-step.active { padding-top: calc(.625rem - 2px); }
  .cds-progress-description { font-size: .625rem; }
  .icp-section-heading { flex-direction: column; }
  .icp-field-grid { grid-template-columns: minmax(0, 1fr); }
  .two-col { grid-template-columns: minmax(0, 1fr); }
  .generated-query { grid-template-columns: minmax(0, 1fr) auto; }
  .generated-query .query-note { grid-column: 1 / -1; }
  .integration-summary { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .integration-summary-card { padding: .625rem; }
  .integration-summary-label, .integration-summary-card .field-help { font-size: .625rem; }
  .integration-summary-value { font-size: 1.25rem; }
  .integration-card-header { flex-wrap: wrap; }
  .integration-card-footer { align-items: flex-start; flex-direction: column; }
  .integration-footer-actions { width: 100%; }
  .integration-footer-actions .btn { flex: 1; justify-content: center; }
  .record-detail-list { grid-template-columns: minmax(0, 1fr); }
  .action-bar { flex-direction: column; }
  .action-buttons { width: 100%; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .action-buttons .btn { justify-content: center; min-width: 0; }
  .action-buttons #btnNext { grid-column: 1 / -1; }
}

@media (max-width: 600px) {
  .app-shell:not(.sidebar-collapsed) .side-nav .nav-section-label { display: block; }
  .app-shell:not(.sidebar-collapsed) .side-nav .side-nav-item { justify-content: flex-start; padding: 0 .875rem; }
  .app-shell:not(.sidebar-collapsed) .side-nav .side-nav-item span { display: inline; }
  .app-shell:not(.sidebar-collapsed) .side-nav .side-nav-note span:not(.status-dot) { display: inline; }
  .app-shell:not(.sidebar-collapsed) .side-nav .side-nav-footer { display: block; }
}

/* Production auth + Carbon select finishing */
.global-header[hidden], .app-shell[hidden] { display: none !important; }
.header-logout { border: 0; background: transparent; color: #f4f4f4; padding: .5rem .75rem; font: inherit; cursor: pointer; }
.header-logout:hover { background: #393939; }
.auth-gate { min-height: 100dvh; display: grid; place-items: center; padding: 1.25rem; background: #f4f4f4; }
.auth-gate[hidden] { display: none !important; }
.auth-card { width: min(28rem, 100%); background: #fff; border-top: 4px solid #0f62fe; padding: clamp(1.25rem, 5vw, 2.5rem); box-shadow: 0 2px 6px rgba(0,0,0,.12); display: flex; flex-direction: column; gap: .75rem; }
.auth-eyebrow { color: #0f62fe; font-size: .75rem; font-weight: 600; letter-spacing: .12em; }
.auth-card h1 { font-size: 1.75rem; font-weight: 400; margin: .25rem 0; }
.auth-copy, .auth-footnote { color: #6f6f6f; font-size: .8125rem; line-height: 1.5; }
.auth-card label { margin-top: .5rem; font-size: .75rem; color: #525252; }
.auth-submit { width: 100%; justify-content: center; margin-top: .75rem; min-height: 3rem; }
.auth-mode-toggle { padding: .75rem 0; border: 0; background: transparent; color: #0f62fe; font: inherit; cursor: pointer; text-align: center; }
.auth-message { min-height: 1.25rem; color: #198038; font-size: .8125rem; overflow-wrap: anywhere; }
.auth-message.error { color: #da1e28; }
.auth-footnote { border-top: 1px solid #e0e0e0; padding-top: .875rem; margin-top: .25rem; }
.icp-carbon-select { width: 100%; min-width: 0; }
.cds-select-trigger { display: flex; align-items: center; justify-content: space-between; gap: .75rem; width: 100%; min-width: 0; min-height: 2.5rem; padding: .5rem .75rem; border: 0; border-bottom: 1px solid #8d8d8d; background: #f4f4f4; color: #161616; text-align: left; font: inherit; cursor: pointer; }
.cds-select-trigger:hover { background: #e8e8e8; }
.cds-select-trigger:focus-visible { outline: 2px solid #0f62fe; outline-offset: -2px; }
.cds-select-current { display: flex; align-items: center; min-width: 0; gap: .5rem; overflow-wrap: anywhere; }
.cds-select-chevron { flex: 0 0 auto; color: #525252; }
.cds-select-menu { position: absolute; z-index: 1200; left: 0; right: 0; top: calc(100% + 1px); max-height: min(19rem, 55dvh); overflow: auto; background: #fff; border: 1px solid #c6c6c6; box-shadow: 0 4px 12px rgba(0,0,0,.18); }
.cds-select-menu[hidden] { display: none !important; }
.cds-select { position: relative; }
.cds-select-option { display: flex; align-items: center; gap: .625rem; width: 100%; min-height: 2.5rem; padding: .5rem .75rem; border: 0; background: #fff; color: #161616; font: inherit; font-size: .875rem; text-align: left; cursor: pointer; }
.cds-select-option:hover, .cds-select-option[aria-selected="true"] { background: #e8e8e8; }
.cds-select-option[aria-selected="true"]::after { content: "✓"; margin-left: auto; color: #0f62fe; font-weight: 600; }
.flag-circle { width: 1.35rem; height: 1.35rem; display: inline-flex; align-items: center; justify-content: center; flex: 0 0 1.35rem; border-radius: 50%; background: #f4f4f4; font-size: 1rem; line-height: 1; overflow: hidden; }
.icp-field-grid { align-items: start; }
.icp-field { position: relative; }
.icp-field label { display: block; }
.empty-state { padding: 2rem 1.25rem; color: #525252; background: #f4f4f4; }
.empty-state h3 { margin-bottom: .5rem; font-size: 1rem; color: #161616; }
.empty-state p { max-width: 52rem; line-height: 1.55; }
.discover-panel .panel-header { align-items: center; gap: 1rem; }
.discover-panel .panel-header p { margin-top: .25rem; }
@media (max-width: 600px) {
  .header-logout { padding-inline: .4rem; font-size: .75rem; }
  .auth-card { padding: 1.25rem; }
  .discover-panel .panel-header { align-items: flex-start; flex-direction: column; }
  .discover-panel .panel-header .btn { width: 100%; justify-content: center; }
  .cds-select-menu { max-height: 45dvh; }
}

body:not(.authenticated) .global-header, body:not(.authenticated) .app-shell { display: none !important; }
body:not(.authenticated) .auth-gate { display: grid; }
body.authenticated .auth-gate { display: none; }

